#include <stdlib.h>

#define BUFFER_SIZE 1024

void* dinamic_buffer(void* ptr, size_t new_size) {
    // Verificamos si el puntero es nulo
    if (ptr == NULL) {
        ptr = malloc(new_size);
        if (ptr == NULL) {
            printf("Error al asignar memoria\n");
            exit(1);
        }
    }

    // Verificamos si la nueva tamaño es 0
    if (new_size == 0) {
        free(ptr);
        ptr = NULL;
        return ptr;
    }

    // Verificamos si la memoria se puede reasignar
    if (realloc(ptr, new_size) == NULL) {
        // Si la reasignación falla, liberamos la memoria y devolvemos NULL
        free(ptr);
        ptr = NULL;
        return NULL;
    }

    // Si la reasignación es exitosa, actualizamos el puntero
    ptr = realloc(ptr, new_size);
    return ptr;
}
