    STATE_IDLE,
    STATE_READING
} state_t;

typedef struct {
    state_t state;
    uint32_t samples_read;
    float sum_rms;
} i2c_task_t;

static i2c_task_t task = {
    .state = STATE_IDLE,
    .samples_read = 0,
    .sum_rms = 0.0f
};

static void i2c_task_task(void *pvTaskStruct)
{
    i2c_task_t *task = (i2c_task_t *)pvTaskStruct;

    while (1) {
        switch (task->state) {
            case STATE_IDLE:
                task->state = STATE_READING;
                break;
            case STATE_READING:
                if (i2c_read(I2C_PORT, I2C_ADDRESS, 2)) {
